function microTick(){if(!microPaused&&!document.hidden&&!document.body.classList.contains('v4nomotion')){microT+=1; if(microFrame++%2===0 && el('page-v4lab')&&!el('page-v4lab').hidden && !el('v4panel-micro').hidden)drawMicro()}microLoop=requestAnimationFrame(microTick)}
['v4MicroAmount','v4MicroTemp','v4MicroType','v4MicroMix'].forEach(id=>el(id).addEventListener('input',()=>{microStatus();drawMicro()}));el('v4MicroPause').addEventListener('click',()=>{microPaused=!microPaused;el('v4MicroPause').textContent=microPaused?'▶ Animation fortsetzen':'⏸ Animation anhalten';drawMicro()});const zoomInfo={1:'×1: Überblick über das ganze Becherglas. Jeder Punkt steht für viele Teilchen.',2:'×2: Ausschnitt doppelt vergrößert – die Teilchen verteilen sich gleichmäßig im Wasser.',4:'×4: Jetzt erkennst du einzelne Wassermoleküle (rot: Sauerstoff, weiß: Wasserstoff) und die gelösten Teilchen.',8:'×8: Ein Teilchen ganz genau: Wassermoleküle umhüllen das gelöste Teilchen.'};function setMicroZoom(z){microZoom=z;all('[data-micro-zoom]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.microZoom===z)));const info=el('v4MicroZoomInfo');if(info)info.textContent=zoomInfo[z];microStatus();drawMicro()}all('[data-micro-zoom]').forEach(b=>b.addEventListener('click',()=>setMicroZoom(+b.dataset.microZoom)));microStatus();drawMicro();if(typeof requestAnimationFrame==='function')microLoop=requestAnimationFrame(microTick);
// -- HEATING CURVE, point recording, own values, CSV and graph as SVG without remote library.
let clock=0,measurements=[];if(!Array.isArray(data.ownHeat))data.ownHeat=[];
const HEAT_SUBST={water:{name:'Wasser',t0:373.15,dh:40660,rate:1},ethanol:{name:'Ethanol',t0:351.45,dh:38560,rate:1.7}};
const round1=v=>Math.round(v*10)/10;
