const heatPressure=()=>{const v=+el('v4PressureNum').value;return Math.min(1500,Math.max(300,Number.isFinite(v)&&v>0?v:1013))};
const heatPower=()=>{const v=+el('v4PowerNum').value;return Math.min(2000,Math.max(100,Number.isFinite(v)&&v>0?v:600))};
// Clausius-Clapeyron estimate of the boiling point for the chosen pressure.
const currentBP=()=>{const s=heatSubst();return round1(1/(1/s.t0-8.314/s.dh*Math.log(heatPressure()/1013.25))-273.15)};
function currentTemp(){return round1(Math.min(currentBP(),20+clock*heatPower()/30*heatSubst().rate))}
function chartMaxT(){return Math.max(12,...data.ownHeat.map(p=>Math.ceil(p.t/2)*2))}
function updateGraphRead(){el('v4Clock').textContent=clock+' min';el('v4Degrees').textContent=currentTemp().toLocaleString('de-DE')+' °C';el('v4NPoints').textContent=measurements.length;el('v4BPVal').textContent=currentBP().toLocaleString('de-DE')+' °C';el('v4GraphData').innerHTML=measurements.length?measurements.map(p=>`<span>${p.t} min: ${p.deg.toLocaleString('de-DE')} °C</span>`).join(''):'Noch keine Messpunkte gespeichert.';
 const own=el('v4OwnList');if(own)own.innerHTML=data.ownHeat.length?[...data.ownHeat].sort((a,b)=>a.t-b.t).map((p,i)=>`<span>${String(p.t).replace('.',',')} min: ${String(p.deg).replace('.',',')} °C <button class="v4mini" data-own-del="${data.ownHeat.indexOf(p)}" aria-label="Wert ${p.t} Minuten löschen">✕</button></span>`).join(''):'Noch keine eigenen Werte.';
 all('[data-own-del]').forEach(b=>b.addEventListener('click',()=>{data.ownHeat.splice(+b.dataset.ownDel,1);save();updateGraphRead()}));renderChart()}
function renderChart(){const svg=el('v4GraphSvg');if(!svg)return;const maxT=chartMaxT(),px=t=>65+t/maxT*545,py=d=>300-(d/120)*256,stepT=maxT>16?5:2;let out='';for(let t=0;t<=maxT;t+=stepT)out+=`<line x1="${px(t)}" y1="25" x2="${px(t)}" y2="300" stroke="var(--line)"/><text x="${px(t)}" y="322" text-anchor="middle" fill="var(--ink)" font-size="13">${t}</text>`;for(let d=0;d<=120;d+=20)out+=`<line x1="65" y1="${py(d)}" x2="610" y2="${py(d)}" stroke="var(--line)"/><text x="49" y="${py(d)+4}" text-anchor="end" fill="var(--ink)" font-size="13">${d}</text>`;out+='<line x1="65" y1="25" x2="65" y2="300" stroke="var(--ink)" stroke-width="2"/><line x1="65" y1="300" x2="610" y2="300" stroke="var(--ink)" stroke-width="2"/><text x="342" y="346" fill="var(--ink)" text-anchor="middle" font-size="14">Zeit in Minuten</text><text x="20" y="165" fill="var(--ink)" text-anchor="middle" font-size="14" transform="rotate(-90 20 165)">Temperatur in °C</text>';
 const bp=currentBP();out+=`<line x1="65" x2="610" y1="${py(bp)}" y2="${py(bp)}" stroke="#c0262d" stroke-dasharray="7 6" stroke-width="2"/><text x="606" y="${py(bp)-7}" text-anchor="end" fill="#c0262d" font-size="13" font-weight="700">Siedetemperatur ${heatSubst().name} ≈ ${bp.toLocaleString('de-DE')} °C</text>`;
 if(measurements.length){const sorted=[...measurements].sort((a,b)=>a.t-b.t);out+=`<polyline points="${sorted.map(p=>px(p.t)+','+py(p.deg)).join(' ')}" stroke="#0e8689" stroke-width="4" fill="none"/>`;for(const p of sorted)out+=`<circle cx="${px(p.t)}" cy="${py(p.deg)}" r="6" fill="#e49636" stroke="#fff" stroke-width="2"><title>Modell: ${p.t} min, ${p.deg} °C</title></circle>`;}
 if(data.ownHeat.length){const own=[...data.ownHeat].sort((a,b)=>a.t-b.t);if(own.length>1)out+=`<polyline points="${own.map(p=>px(p.t)+','+py(Math.max(0,Math.min(120,p.deg)))).join(' ')}" stroke="#7d4fc4" stroke-width="3" stroke-dasharray="6 4" fill="none"/>`;for(const p of own)out+=`<rect x="${px(p.t)-6}" y="${py(Math.max(0,Math.min(120,p.deg)))-6}" width="12" height="12" transform="rotate(45 ${px(p.t)} ${py(Math.max(0,Math.min(120,p.deg)))})" fill="#7d4fc4" stroke="#fff" stroke-width="2"><title>Eigener Wert: ${p.t} min, ${p.deg} °C</title></rect>`;}
 svg.innerHTML=out}
function resetSeries(msg){if(measurements.length||clock){clock=0;measurements=[];status('v4GraphFeedback',msg)}}
function syncPreset(selId,numId){const sel=el(selId),num=+el(numId).value,match=[...sel.options].find(o=>o.value!=='custom'&&+o.value===num);sel.value=match?match.value:'custom'}
el('v4Power').addEventListener('change',()=>{if(el('v4Power').value!=='custom')el('v4PowerNum').value=el('v4Power').value;else el('v4PowerNum').focus();resetSeries('Die Heizleistung hat sich verändert. Für einen fairen Vergleich startet eine neue Messreihe.');updateGraphRead()});
