el('v4PressureNum').addEventListener('change',()=>{el('v4PressureNum').value=heatPressure();syncPreset('v4Pressure','v4PressureNum');resetSeries('Neuer Luftdruck eingetragen. Die Messreihe beginnt neu.');updateGraphRead()});
