el('v4HeatSubst').addEventListener('change',()=>{resetSeries('Neuer Stoff gewählt. Die Messreihe beginnt neu.');updateGraphRead()});
el('v4GraphNext').addEventListener('click',()=>{if(clock<12)clock++;else status('v4GraphFeedback','Die Messreihe endet nach 12 Minuten. Beginne eine neue Messung.');updateGraphRead()});el('v4GraphSave').addEventListener('click',()=>{if(measurements.find(p=>p.t===clock)){status('v4GraphFeedback','Für diese Minute existiert bereits ein Messpunkt.',false);return}measurements.push({t:clock,deg:currentTemp()});updateGraphRead();status('v4GraphFeedback','Messpunkt gespeichert. Miss noch an weiteren Zeitpunkten.',true)});el('v4GraphReset').addEventListener('click',()=>{clock=0;measurements=[];updateGraphRead();status('v4GraphFeedback','Neue Messreihe: Bitte bei Minute 0 beginnen.')});
el('v4GraphCheck').addEventListener('click',()=>{const bp=currentBP(),sorted=[...measurements].sort((a,b)=>a.t-b.t),plateau=sorted.filter(p=>p.deg===bp);if(measurements.length<4){status('v4GraphFeedback','Erfasse mindestens 4 verschiedene Messpunkte und möglichst auch zwei beim Sieden.',false);return}if(plateau.length<2){status('v4GraphFeedback','Gute Messreihe! Um das Siedeplateau zu untersuchen, miss weiter, bis die Siedetemperatur zweimal erreicht wird.');return}status('v4GraphFeedback',`Auswertung: Der Graph steigt zunächst an und zeigt dann ungefähr bei ${bp.toLocaleString('de-DE')} °C ein Plateau. Bei ${heatPressure()} hPa siedet ${heatSubst().name} im Modell bei etwa ${bp.toLocaleString('de-DE')} °C. Bei gleichbleibendem Druck bleibt die Temperatur während des Siedens etwa konstant.`,true);mark('graph')});
el('v4OwnAdd').addEventListener('click',()=>{const t=parseFloat(String(el('v4OwnTime').value).replace(',','.')),d=parseFloat(String(el('v4OwnTemp').value).replace(',','.'));if(!Number.isFinite(t)||t<0||t>30){status('v4OwnFeedback','Bitte eine Zeit zwischen 0 und 30 Minuten eintragen.',false);return}if(!Number.isFinite(d)||d<-20||d>150){status('v4OwnFeedback','Bitte eine Temperatur zwischen −20 und 150 °C eintragen.',false);return}const old=data.ownHeat.findIndex(p=>p.t===t);if(old>=0)data.ownHeat.splice(old,1);data.ownHeat.push({t:round1(t),deg:round1(d)});save();updateGraphRead();el('v4OwnTime').value=String(round1(t+1));el('v4OwnTemp').value='';el('v4OwnTemp').focus();status('v4OwnFeedback',`Eingetragen: ${round1(t)} min, ${round1(d)} °C. Er erscheint als violette Raute im Diagramm.`,true)});
