let sceneNo=0,found=new Set(),lastSafe=-1;
function renderScene(){sceneNo=+el('v4SceneSelect').value;found=new Set(data.detect[sceneNo]||[]);const s=scenes[sceneNo];
 const spot=(p,i,kind)=>{const done=kind==='h'&&found.has(i),okSeen=kind==='s'&&lastSafe===i;return `<g class="det-spot${done?' found':''}${okSeen?' okseen':''}" data-${kind==='h'?'hazard':'safe'}="${i}" tabindex="0" role="button" aria-label="Bildstelle untersuchen"><circle class="det-hit" cx="${p.x}" cy="${p.y}" r="${p.r}"/>${done?`<circle class="det-ring" cx="${p.x}" cy="${p.y}" r="${p.r}"/><circle cx="${p.x+p.r*.7}" cy="${p.y-p.r*.7}" r="13" fill="#1d8a5f"/><text x="${p.x+p.r*.7}" y="${p.y-p.r*.7+5}" text-anchor="middle" font-size="15" font-weight="900" fill="#fff">${i+1}</text>`:''}${okSeen?`<circle class="det-okring" cx="${p.x}" cy="${p.y}" r="${p.r}"/>`:''}</g>`};
 const spots=[...s.spots.map((p,i)=>({p,i,k:'h'})),...s.safe.map((p,i)=>({p,i,k:'s'}))].sort((a,b)=>a.p.x-b.p.x);
 el('v4SceneBoard').innerHTML=`<div class="v4sceneheader">Laborszene ${sceneNo+1} von ${scenes.length}: ${s.title}</div><div class="det-scene"><svg viewBox="0 0 800 450" role="img" aria-labelledby="detTitle${sceneNo}"><title id="detTitle${sceneNo}">Gezeichnete Laborszene „${s.title}“ mit versteckten Gefahren</title><g class="det-art" data-det-miss="1">${s.art()}</g>${spots.map(x=>spot(x.p,x.i,x.k)).join('')}<circle class="det-hint" cx="-100" cy="-100" r="10"/></svg></div><div class="det-found">${s.spots.map((p,i)=>found.has(i)?`<div class="det-card"><b>${i+1}. ${p.t}</b><span>✔ So ist es richtig: ${p.f}</span></div>`:'').join('')||'<p class="v4small">Noch keine Gefahr entdeckt. Tippe im Bild auf die Stellen, die dir gefährlich vorkommen.</p>'}</div>`;
 el('v4SceneCount').textContent=`${found.size} von 4 gefunden`;
 const act=(node,fn)=>{node.addEventListener('click',fn);node.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}})};
 all('[data-hazard]',el('v4SceneBoard')).forEach(b=>act(b,()=>{const i=+b.dataset.hazard,p=s.spots[i],was=found.has(i);found.add(i);data.detect[sceneNo]=Array.from(found);lastSafe=-1;save();renderScene();status('v4SceneFeedback',(was?'Schon gefunden: ':'Gefahr entdeckt! ')+`${p.t}. ${p.f}`+(found.size===4?' 🎉 Alle vier Gefahren dieser Szene gefunden!':''),true);if(scenes.every((x,j)=>(data.detect[j]||[]).length===4))mark('detect')}));
 all('[data-safe]',el('v4SceneBoard')).forEach(b=>act(b,()=>{lastSafe=+b.dataset.safe;renderScene();status('v4SceneFeedback','Keine Gefahr: '+s.safe[lastSafe].t)}));
 const art=el('v4SceneBoard').querySelector('[data-det-miss]');if(art)art.addEventListener('click',()=>status('v4SceneFeedback','Hier ist keine der gesuchten Gefahren. Schau dir Personen, Geräte, Tisch und Boden genau an.'))}
el('v4SceneSelect').addEventListener('change',()=>{lastSafe=-1;renderScene();status('v4SceneFeedback','Untersuche die neue Szene.');});
el('v4SceneHint').addEventListener('click',()=>{const s=scenes[sceneNo],i=[0,1,2,3].find(j=>!found.has(j));if(i===undefined){status('v4SceneFeedback','Alle Gefahren gefunden! Wechsle zur nächsten Szene.');return}const p=s.spots[i],h=el('v4SceneBoard').querySelector('.det-hint');if(h){h.setAttribute('cx',p.x);h.setAttribute('cy',p.y);h.setAttribute('r',p.r+34);h.classList.remove('show');void h.getBoundingClientRect();h.classList.add('show')}status('v4SceneFeedback','💡 Hinweis: '+p.h)});
el('v4SceneNext').addEventListener('click',()=>{el('v4SceneSelect').value=(sceneNo+1)%scenes.length;lastSafe=-1;renderScene();status('v4SceneFeedback','Neue Szene: entdecke vier Gefahren.')});renderScene();
