let escUnlocked=false;
function renderEscape(){const i=Math.min(escapeTasks.length,Math.max(0,data.escape||0));el('v4EscapeDots').innerHTML=escapeTasks.map((_,n)=>`<span class="${n<i?'done':''}"></span>`).join('');el('v4EscapeStep').textContent=i===escapeTasks.length?'Geschafft':'Raum '+(i+1)+' von '+escapeTasks.length;if(i===escapeTasks.length){el('v4EscapeTitle').textContent='Die Forschungskiste ist offen!';el('v4EscapeText').textContent='Alle wissenschaftlichen und sicherheitsbezogenen Rätsel sind gelöst. Du hast die Kiste geöffnet.';el('v4EscapeChoices').innerHTML='';el('v4RoomIcon').textContent='🏆';el('v4EscapeNext').disabled=true;status('v4EscapeFeedback','Herzlichen Glückwunsch! Im Forscherbuch kannst du deine Erkenntnisse festhalten.',true);mark('escape');return}const q=escapeTasks[i];el('v4EscapeTitle').textContent=q.title;el('v4EscapeText').textContent=q.story;el('v4RoomIcon').textContent=q.icon;el('v4EscapeChoices').innerHTML=q.opts.map((o,j)=>`<button data-v4escape="${j}">${clean(o)}</button>`).join('');escUnlocked=false;el('v4EscapeNext').disabled=true;status('v4EscapeFeedback','Wähle eine Lösung oder nutze einen Hinweis.');all('[data-v4escape]').forEach(b=>b.addEventListener('click',()=>{if(escUnlocked)return;const j=+b.dataset.v4escape;if(j!==q.ok){b.classList.add('wrong');status('v4EscapeFeedback','Noch nicht. '+q.hint,false);return}b.classList.add('correct');escUnlocked=true;el('v4EscapeNext').disabled=false;status('v4EscapeFeedback',q.why,true)}))}
el('v4EscapeNext').addEventListener('click',()=>{if(!escUnlocked)return;data.escape=Math.min(escapeTasks.length,data.escape+1);save();renderEscape()});el('v4EscapeHint').addEventListener('click',()=>{if(data.escape<escapeTasks.length)status('v4EscapeFeedback','Hinweis: '+escapeTasks[data.escape].hint)});el('v4EscapeRestart').addEventListener('click',()=>{data.escape=0;save();renderEscape()});renderEscape();
// -- COACH: sequenced explanation, no hallucinated AI or network requests.
const coach={dissolve:{q:'Warum löst sich in 200 ml Wasser mehr Salz als in 100 ml?',tips:['Vergleiche die Wassermengen.','In mehr Wasser haben mehr Teilchen Platz.','Die maximale Lösungsmenge ist näherungsweise proportional zur Wassermenge.'],answer:'Bei gleicher Temperatur löst sich in der doppelten Wassermenge näherungsweise die doppelte Salzmasse, bis eine gesättigte Lösung erreicht ist.'},boil:{q:'Warum bleibt die Temperatur beim Sieden trotz weiterer Wärmezufuhr ungefähr gleich?',tips:['Es geht um den Übergang von flüssig zu gasförmig.','Die Energie wird für den Phasenübergang benötigt.','Bei gleichbleibendem Druck gibt es ein Siedeplateau.'],answer:'Während des Siedens wird zugeführte Energie hauptsächlich für das Verdampfen verwendet. Bei konstantem Druck bleibt die Temperatur reinen Wassers idealisiert am Siedepunkt.'},matter:{q:'Ein Goldring besteht aus Gold: Was ist Stoff, was ist Körper?',tips:['Was kann man anfassen?','Ein konkreter Gegenstand ist ein Körper.','Das Material heißt Stoff.'],answer:'Der Ring ist ein Körper, Gold ist sein Stoff. Ein Körper kann auch aus mehreren Stoffen bestehen.'},safety:{q:'Warum darfst du eine unbekannte Flüssigkeit nicht direkt riechen?',tips:['Es könnten gefährliche Dämpfe entstehen.','Schon kleine eingeatmete Mengen können schädlich sein.','Im Zweifel wird gar keine Geruchsprobe gemacht.'],answer:'Unbekannte Chemikalien dürfen ohne Freigabe nicht gerochen werden. Wenn erlaubt, wird der Geruch mit Abstand vorsichtig zugefächelt.'},filter:{q:'Kannst du gelöstes Salz mit gewöhnlichem Filterpapier aus Wasser filtern?',tips:['Was bleibt im Filter?','Sehr kleine gelöste Teilchen passieren das Papier.','Filtrieren trennt unlösliche Teilchen ab.'],answer:'Nein. Gelöstes Salz passiert gewöhnliches Filterpapier. Filtrieren eignet sich dagegen gut zum Trennen von Sand und Wasser.'},burner:{q:'Warum ist eine blaue rauschende Flamme heißer als eine gelbe leuchtende?',tips:['Es hängt mit der Luftzufuhr zusammen.','Mit besserer Luftzufuhr erfolgt meist eine vollständigere Verbrennung.','Denk an Energieverteilung und sichtbare Rußteilchen.'],answer:'Durch ausreichende Luftzufuhr verbrennt das Gas weitgehend vollständig. Die blaue Flamme erreicht dabei höhere Temperaturen; die gelbe kann rußen und ist gut sichtbar.'}};
let coachHint=0;function renderCoach(){coachHint=0;const q=coach[el('v4CoachTopic').value];el('v4CoachQuestion').textContent=q.q;status('v4CoachText','Überlege zunächst selbst. Wenn du nicht weiterkommst, fordere einen schrittweisen Hinweis an.')}
el('v4CoachTopic').addEventListener('change',renderCoach);el('v4CoachAgain').addEventListener('click',renderCoach);el('v4CoachHint').addEventListener('click',()=>{const q=coach[el('v4CoachTopic').value];if(coachHint<q.tips.length){status('v4CoachText','Tipp '+(coachHint+1)+'/3: '+q.tips[coachHint]);coachHint++}else status('v4CoachText','Alle Hinweise gelesen. Versuche jetzt, die Erklärung selbst zu formulieren, bevor du aufdeckst.')});el('v4CoachAnswer').addEventListener('click',()=>{status('v4CoachText','Erklärung: '+coach[el('v4CoachTopic').value].answer,true)});renderCoach();
// -- Digital burner safety certificate, not a real operating permit.
const license=[
['Was machst du vor einem Experiment mit Gasbrenner?', ['Ohne Aufsicht beginnen','Anweisungen und Sicherheitseinweisung beachten','Tasche neben Flamme stellen'],1,'Gasbrenner nur mit Erlaubnis und nach Einweisung.',['Falsch: Ohne Aufsicht und Einweisung darf der Brenner nie benutzt werden – bei einem Fehler kann niemand helfen.','Vor dem Experiment braucht es Einweisung und Erlaubnis: Nur so kennst du die Handgriffe und jemand passt auf.','Falsch: Eine Tasche neben der Flamme kann Feuer fangen und ist eine Stolperfalle.']],
['Welche Kleidung ist am Wärmeplatz wichtig?', ['Offene weite Ärmel','Lange Haare gesichert und passende Kleidung','Schal über Flamme halten'],1,'Lose Kleidung und Haare können Feuer fangen.',['Falsch: Offene weite Ärmel können in die Flamme geraten und brennen sehr schnell.','Gesicherte Haare und enganliegende Kleidung können nicht versehentlich in die Flamme gelangen.','Falsch: Ein Schal über der Flamme ist brennbares Material direkt an der Zündquelle – höchste Brandgefahr.']],
['Was gilt bei einer unbeaufsichtigten Flamme?', ['Ignorieren','Abstand halten und Lehrkraft sofort informieren','Mit Papier abdecken'],1,'Eine Flamme niemals unbeaufsichtigt lassen.',['Falsch: Ignorieren lässt die Gefahr bestehen – die Flamme kann etwas entzünden, ohne dass es jemand bemerkt.','Abstand schützt dich, und die Lehrkraft kann die Gefahr fachgerecht beseitigen.','Falsch: Papier ist brennbar! Es würde sofort Feuer fangen statt die Flamme zu ersticken.']],
['Welche Flammenzone ist bei der blauen Flamme im Schulmodell besonders heiß?', ['Im inneren Kegel','Knapp über der Innenkegelspitze','Am Brennersockel'],1,'Knapp oberhalb der inneren Kegelspitze.',['Falsch: Im inneren Kegel ist das Gas-Luft-Gemisch noch nicht vollständig verbrannt – dort ist es vergleichsweise kühl.','Knapp über der Spitze des inneren Kegels verbrennt das Gemisch vollständig – dort ist die heißeste Zone.','Falsch: Am Sockel tritt das Gemisch erst aus; dort brennt es noch gar nicht richtig.']],
['Was ist bei einer Störung oder Gasgeruch richtig?', ['Weiterarbeiten','Lehrkraft sofort informieren und ihren Anweisungen folgen','Eigenständig an Anschlüssen schrauben'],1,'Bei Störungen nicht experimentieren und sofort Bescheid geben.',['Falsch: Weiterarbeiten bei Gasgeruch ist lebensgefährlich – austretendes Gas kann sich entzünden.','Die Lehrkraft kennt die Notfallschritte (Gas abstellen, lüften) und entscheidet, wie es weitergeht.','Falsch: An Gasanschlüssen dürfen nur Fachleute arbeiten – selbst schrauben kann ein Leck vergrößern.']],
['Warum heißt die gelbe Flamme leuchtend?', ['Sie enthält glühende Partikel und ist gut sichtbar','Sie ist immer heißer','Sie braucht keine Luft'],0,'Die gelbe Flamme ist gut zu sehen und kann rußen.',['Glühende Kohlenstoffteilchen machen die Flamme hell sichtbar – darum stellt man sie ein, wenn der Brenner gerade nicht benutzt wird.','Falsch: Die gelbe Flamme ist kühler als die blaue – „leuchtend“ sagt nichts über Hitze.','Falsch: Auch die gelbe Flamme braucht Luft; sie bekommt nur weniger davon, weil die Luftzufuhr geschlossen ist.']]
];
let lic={i:0,correct:0,locked:false};function renderLicense(){if(lic.i>=license.length){el('v4LicenseQuestion').textContent=lic.correct===6?'🏆 Alle Sicherheitsfragen richtig!':'Du hast den Sicherheitstest abgeschlossen.';el('v4LicenseChoices').innerHTML='';el('v4LicenseCount').textContent='Auswertung';status('v4LicenseFeedback',`${lic.correct}/6 richtig. ${lic.correct===6?'Digitale Lernkontrolle bestanden. Ein praktischer Brennerführerschein muss im Unterricht durch die Lehrkraft bestätigt werden.':'Wiederhole die Regeln und versuche es erneut.'}`,lic.correct===6);el('v4LicenseNext').disabled=true;if(lic.correct===6)mark('license');return}let [q,opts]=license[lic.i];el('v4LicenseCount').textContent=`Frage ${lic.i+1} von 6`;el('v4LicenseQuestion').textContent=q;el('v4LicenseChoices').innerHTML=opts.map((t,j)=>`<button data-lic="${j}">${clean(t)}</button>`).join('');lic.locked=false;el('v4LicenseNext').disabled=true;status('v4LicenseFeedback','Welche Antwort ist sicher?');all('[data-lic]').forEach(b=>b.addEventListener('click',()=>{if(lic.locked)return;lic.locked=true;let good=+b.dataset.lic===license[lic.i][2];if(good)lic.correct++;b.classList.add(good?'correct':'wrong');all('[data-lic]').forEach(x=>x.disabled=true);const whys=license[lic.i][4]||[],chosen=+b.dataset.lic,corr=license[lic.i][2];status('v4LicenseFeedback',good?('Richtig. '+(whys[chosen]||license[lic.i][3])):('Nicht ganz. '+(whys[chosen]||'')+' Richtig ist: „'+license[lic.i][1][corr]+'“ – '+(whys[corr]||license[lic.i][3])),good);el('v4LicenseNext').disabled=false}))}
el('v4LicenseNext').addEventListener('click',()=>{if(!lic.locked)return;lic.i++;renderLicense()});el('v4LicenseReset').addEventListener('click',()=>{lic={i:0,correct:0,locked:false};renderLicense()});renderLicense();
// -- Forscher journal: all data saved locally. No unescaped HTML injection.
const journalFields={date:'v4JournalDate',title:'v4JournalTitle',question:'v4JournalQuestion',hypothesis:'v4JournalHypothesis',steps:'v4JournalSteps',observation:'v4JournalObservation',evaluation:'v4JournalEvaluation',errors:'v4JournalErrors'};
function readNotebook(){return Object.fromEntries(Object.entries(journalFields).map(([k,id])=>[k,el(id).value]))}
function syncNotebook(){data.notebook=readNotebook();save()}
for(let [k,id] of Object.entries(journalFields)){const n=el(id);n.value=data.notebook[k]||'';n.addEventListener('input',syncNotebook)}
if(!el('v4JournalDate').value){el('v4JournalDate').value=new Date().toLocaleDateString('en-CA');syncNotebook()}
el('v4JournalSave').addEventListener('click',()=>{syncNotebook();status('v4JournalFeedback','Protokoll auf diesem Gerät gespeichert.',true);mark('journal')});el('v4JournalReview').addEventListener('click',()=>{const r=readNotebook(),filled=['title','question','hypothesis','steps','observation','evaluation'].filter(k=>r[k].trim()).length;const errorNote=r.errors.trim()?' Du hast auch mögliche Fehlerquellen notiert.':' Denke auch an mögliche Fehlerquellen.';status('v4JournalFeedback',`${filled} von 6 wesentlichen Bereichen sind ausgefüllt. ${filled===6?'Sehr gut! Prüfe noch, ob Beobachtung und Erklärung getrennt sind.':'Ergänze noch fehlende Angaben.'}${errorNote}`,filled===6);if(filled===6)mark('journal')});
function journalText(){const r=readNotebook();return ['Chemie-Forscherprotokoll · Klasse 5','Datum: '+r.date,'Experiment: '+r.title,'','Fragestellung:\n'+r.question,'','Vermutung mit Begründung:\n'+r.hypothesis,'','Material:\n'+((data.notebook.material||[]).join(', ')||'–'),'','Durchführung:\n'+r.steps,'','Beobachtung:\n'+r.observation,'','Auswertung:\n'+r.evaluation,'','Mögliche Fehlerquellen:\n'+r.errors].join('\n')}
el('v4JournalDownload').addEventListener('click',()=>{syncNotebook();download(journalText(),'mein-chemie-forscherprotokoll.txt','text/plain;charset=utf-8')});
function printArea(cls){document.body.classList.add(cls);window.print();setTimeout(()=>document.body.classList.remove(cls),500)}
el('v4JournalPrint').addEventListener('click',()=>printArea('v4printjournal'));

// -- Material list with custom entries
const MAT_SUGGEST=['Becherglas','Erlenmeyerkolben','Messzylinder','Reagenzglas','Reagenzglasständer','Glasstab','Metallstab','Holzstab','Thermometer','Stativ mit Klemme','Dreifuß','Drahtnetz','Gasbrenner','Teelicht','Trichter mit Filterpapier','Uhrglas','Spatel','Waage','Schutzbrille','Wasser','Kochsalz','Zucker','Wachsstücke'];
if(!Array.isArray(data.notebook.material))data.notebook.material=[];
function renderMat(){const grid=el('v4MatGrid');if(!grid)return;grid.innerHTML=MAT_SUGGEST.map(m=>{const on=data.notebook.material.includes(m);return '<label class="v4matopt'+(on?' on':'')+'"><input type="checkbox" '+(on?'checked':'')+' value="'+m+'"/> '+m+'</label>'}).join('');all('input',grid).forEach(c=>c.addEventListener('change',()=>{const v=c.value;if(c.checked){if(!data.notebook.material.includes(v))data.notebook.material.push(v)}else data.notebook.material=data.notebook.material.filter(x=>x!==v);save();renderMat()}));const extra=data.notebook.material.filter(m=>!MAT_SUGGEST.includes(m));el('v4MatChips').innerHTML=extra.length?('Eigene Einträge: '+extra.map(m=>'<span class="v4chip">'+m.replace(/[<>&]/g,'')+' <button type="button" data-matdel="'+m.replace(/"/g,'&quot;')+'" aria-label="Eintrag entfernen">×</button></span>').join(' ')):'';all('[data-matdel]').forEach(b=>b.addEventListener('click',()=>{data.notebook.material=data.notebook.material.filter(x=>x!==b.dataset.matdel);save();renderMat()}))}
if(el('v4MatAdd')){el('v4MatAdd').addEventListener('click',()=>{const v=el('v4MatCustom').value.trim().slice(0,60);if(!v)return;if(!data.notebook.material.includes(v))data.notebook.material.push(v);el('v4MatCustom').value='';save();renderMat()});renderMat()}
